node -e '
async function search() {
  const urls = [
    "https://docs.arbitrum.io/build-decentralized-apps/reference/node-providers",
    "https://docs.arbitrum.io/for-devs/dev-tools-and-resources/chain-info",
    "https://docs.arbitrum.io/build-decentralized-apps/reference/contract-addresses",
    "https://docs.arbitrum.io/build-decentralized-apps/reference/useful-addresses",
    "https://raw.githubusercontent.com/OffchainLabs/arbitrum-docs/master/arbitrum-docs/for-devs/dev-tools-and-resources/chain-info.md",
    "https://raw.githubusercontent.com/OffchainLabs/arbitrum-docs/master/arbitrum-docs/build-decentralized-apps/reference/contract-addresses.md"
  ];
  for (const u of urls) {
    try {
      const r = await fetch(u);
      console.log(u, r.status);
    } catch (e) {
      console.log(u, e.message);
    }
  }
}
search();
'

node -e '
async function run() {
  for (const u of [
    "https://docs.arbitrum.io/for-devs/dev-tools-and-resources/chain-info",
    "https://docs.arbitrum.io/build-decentralized-apps/reference/contract-addresses",
    "https://docs.arbitrum.io/how-arbitrum-works/sequencer"
  ]) {
    const r = await fetch(u);
    const html = await r.text();
    const text = html.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<style[\s\S]*?<\/style>/g, "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ");
    console.log("=== " + u + " ===");
    console.log(text.slice(0, 4000));
  }
}
run();
'

